apiVersion: flowmesh/v2
kind: Workflow
metadata: {name: legacy}
spec:
  graph:
    nodes:

      - name: plan
        spec: {taskType: echo, data: {type: list, items: [x]}}
      - name: kid
        spec: {taskType: echo, data: {type: list, items: [x]}}
      - name: fan
        dependsOn: [plan]
        region: {kind: spawn, child: kid}
      - name: collect
        dependsOn: [fan]
        region: {kind: join, completion: all_settled}
      - name: slow
        spec: {taskType: echo, data: {type: list, items: [x]}}
      - name: after
        dependsOn: [collect, slow]
        spec: {taskType: echo, data: {type: list, items: [x]}}

