      - name: b
        spec: {taskType: echo, data: {type: list, items: [x]}}
      - name: m
        dependsOn: [a, b]
        region: {kind: merge}
      - name: slow
        spec: {taskType: echo, data: {type: list, items: [x]}}
      - name: after
        dependsOn: [m, slow]
        spec: {taskType: echo, data: {type: list, items: [x]}}

